kit.scene('fallen', {
  init(kit) {
    const ghosts = [[110, 0.8, 0], [800, 0.85, 1], [250, 0.7, 0], [690, 0.7, 1], [459, 1.05, 0]].map((g) => '<g class="fallen-ghost" style="opacity:0">' + W.guard(g[0], g[1], g[2]) + '</g>').join('');
    this.s = W.shot(kit, {
      id: 'fallen', back: '<rect width="918" height="1027" style="fill:var(--accent);opacity:.18"/>' + ghosts,
      cast: [{ who: 'ravana', x: 590, y: 1750, s: 1.4 }],
      cam: [1.0, 1.06, 459, 520, 448, 505],
      arm: (t) => 30 + 5 * Math.sin(t * 1.0),
      lines: [[46.1, 46.8, 'कुंभकर्ण…', 0, 0], [46.9, 48.0, 'महापार्श्व…', 0, 0], [48.1, 49.6, 'अतिकाय… कुंभ-निकुंभ…', 0, 0], [50.3, 53.9, 'मेघनाद जैसे वीरों का बलिदान…', 0, 0], [54.2, 55.8, 'क्या मैं व्यर्थ जाने दूँ?', 0, 0], [56.0, 57.0, 'कभी नहीं।', 0, 0]],
      extra: (t, stage) => {
        if (!this.gh) this.gh = [...stage.querySelectorAll('.fallen-ghost')];
        const at = [0.55, 1.35, 2.55, 3.05, 4.75];
        this.gh.forEach((g, i) => { g.style.opacity = (kit.eo(kit.clamp01((t - at[i]) / 0.6)) * (1 - kit.clamp01((t - 9.6) / 1.2))).toFixed(3); });
      },
    });
  },
  render(t) { this.s.render(t); },
});
